// Subscribe to values from an observable property that can change
this.WhenAnyValue(x => x.SomeObservableProperty)
    .SwitchSubscribe(value => Console.WriteLine($"Value: {value}"));

// Subscribe to command results, following command property changes
this.WhenAnyValue(x => x.SaveCommand)
    .SwitchSubscribe(result => Console.WriteLine($"Saved: {result}"));

// Subscribe to IsExecuting, following command property changes
this.WhenAnyValue(x => x.LoadCommand)
    .SwitchSubscribe(
        cmd => cmd.IsExecuting,
        isExecuting => IsLoading = isExecuting
    );

// Use with ToProperty to track IsExecuting from a replaceable command
_isBusy = this.WhenAnyValue(x => x.SaveCommand)
    .SwitchSelect(cmd => cmd.IsExecuting)
    .ToProperty(this, x => x.IsBusy);

// Or subscribe directly
this.WhenAnyValue(x => x.DeleteCommand)
    .SwitchSubscribe(
        cmd => cmd.CanExecute,
        canExecute => DeleteButtonEnabled = canExecute
    );

// Subscribe to IsExecuting from a command property that can change
this.WhenAnyValue(x => x.Command)
    .SwitchSubscribe(
        cmd => cmd.IsExecuting,
        isExecuting => IsBusy = isExecuting
    );

// Subscribe to IsExecuting from a command property that can change
this.WhenAnyValue(x => x.Command)
    .SwitchSubscribe(
        cmd => cmd.IsExecuting,
        isExecuting => IsBusy = isExecuting
    );

// Or use with ToProperty
_isBusy = this.WhenAnyValue(x => x.Command)
    .SwitchSelect(cmd => cmd.IsExecuting)
    .ToProperty(this, x => x.IsBusy);

remarks.para:
Creating synchronous reactive commands:


// A synchronous command taking a parameter and returning nothing.
ReactiveCommand<int, Unit> command = ReactiveCommand.Create<int>(x => Console.WriteLine(x));
// This outputs 42 to console.
command.Execute(42).Subscribe();
// A better approach is to invoke a command in response to an Observable<T>.
// InvokeCommand operator respects the command's executability. That is, if
// the command's CanExecute method returns false, InvokeCommand will not
// execute the command when the source observable ticks.
Observable.Return(42).InvokeCommand(command);

Creating asynchronous reactive commands:


// An asynchronous command that waits 2 seconds and returns 42.
var command = ReactiveCommand.CreateFromObservable<Unit, int>(
     _ => Observable.Return(42).Delay(TimeSpan.FromSeconds(2))
);
// Calling the asynchronous reactive command:
// Observable.Return(Unit.Default).InvokeCommand(command);
// Subscribing to values emitted by the command:
command.Subscribe(Console.WriteLine);

